	//error_reporting(0);

	$dirList			= opendir("../Articles");  				
	
	while (($dirPart	= @readdir($dirList)) == true) 
		{  											
			if($dirPart != "." && $dirPart != ".." && $dirPart != "index.php")
				{										
					unlink("../Articles/".$dirPart);
				}
		}
		
	$strDomain		= "http://".$_SERVER["HTTP_HOST"];					
	
	$intCounter		= 0;
	$strKeywords	= explode(",", $_SESSION['Keywords']);
	$strNavigation	= "<br>\n<small style='font-size:9pt;'>\n";
	
	while($intCounter != count($strKeywords))
		{
			$strFile		= str_replace(" ", "_", trim($strKeywords[$intCounter])).".php";			
		    
		    $strTemplate	= file_get_contents("Article.tpl");
			$strContent		= str_replace("%TITLE%", "Index of all ".trim($strKeywords[$intCounter])." Related Articles", $strTemplate);
			$strContent		= str_replace("%KEYWORD%", trim($strKeywords[$intCounter]), $strContent);		   
			$strContent		= str_replace("%DESCRIPTION%", trim($strKeywords[$intCounter]), $strContent);
		    $strContent		= str_replace("%FILE_TYPE%", "IDX", $strContent);		    
			$strContent     = str_replace("%FILE_NAME%", $strFile, $strContent);
			
			$fp				= fopen("../Articles/".$strFile, "w");
			$fw				= fwrite( $fp, $strContent);
			fclose( $fp );

			$strNavigation .= "    <a href='../Articles/".$strFile."' title='Click here for the Index of all ".trim($strKeywords[$intCounter])." Articles...' rel='tag'>".trim($strKeywords[$intCounter])."</a>\n    <br>\n    <br>\n";
					    
			$intCounter++;
		}
		
	$strNavigation .= "</small>";
	
	$fp				= fopen("../Includes/Navigation.php", "w");
	$fw				= fwrite( $fp, $strNavigation );
	fclose( $fp );

	$intCounter		= 0;
	
	while($intCounter != count($strKeywords))
		{				
			$dirList			= opendir("../Content");  				
	
			while (($dirPart	= @readdir($dirList)) == true) 
				{  											
					if($dirPart != "." && $dirPart != ".." && $dirPart != "index.php")
						{										
							$strFile		= str_replace(".txt", ".php", $dirPart);																					
							$strTemp		= explode("<+>" ,file_get_contents("../Content/".$dirPart));														
							
							$strTemplate	= file_get_contents("Article.tpl");
									
							$strContent		= str_replace("%TITLE%", stripslashes(trim($strTemp[1])), $strTemplate);
							$strContent		= str_replace("%KEYWORD%", stripslashes(trim($strTemp[0])), $strContent);		   
							$strContent		= str_replace("%DESCRIPTION%", substr(str_replace("  ", " ", str_replace("nbsp", "", ereg_replace("[^a-z,A-Z,0-9, ]"," ",strip_tags(stripslashes(trim($strTemp[4])))))), 0, 256), $strContent);
							$strContent		= str_replace("%FILE_TYPE%", "ART", $strContent);		    
							$strContent     = str_replace("%FILE_NAME%", str_replace(".php", ".txt", $strFile), $strContent);
									
							$fp				= fopen("../Articles/".$strFile, "w");
							$fw				= fwrite( $fp, $strContent);
							fclose( $fp );																			
						}				
				}
										
			$intCounter++;							
		}	
		
	header('location: XML.php');
?>